if($pid&&$qty&&$qty>0){$s=$conn->prepare("SELECT stock FROM products WHERE id=?");$s->bind_param("i",$pid);$s->execute();$p=$s->get_result()->fetch_assoc();$s->close();if($p&&$qty<=(int)$p['stock'])$_SESSION['cart'][$pid]=min((int)($_SESSION['cart'][$pid]??0)+$qty,(int)$p['stock']);else $_SESSION['notice']='Produk tidak tersedia atau jumlah melebihi stok.';}header('Location: keranjang.php');exit;}
