$pageTitle='Keranjang - Vanguard Outdoor';$checkoutUrl=(!empty($_SESSION['user_id'])&&($_SESSION['role']??'')==='pembeli')?'checkout.php':'login.php?next=checkout.php';$checkoutLabel=(!empty($_SESSION['user_id'])&&($_SESSION['role']??'')==='pembeli')?'Lanjut ke Checkout':'Login untuk Checkout';require_once __DIR__.'/includes/header.php';$items=[];$total=0;$ids=array_map('intval',array_keys($_SESSION['cart']));
